script:
(function () {
  'use strict';
  // HSA contribution limit for 2026 when eligibility or coverage changes during the year
  // (IRS Pub. 969 "Limit on Contributions" and the Form 8889 Line 3 Limitation Chart):
  //   each month you are eligible on the 1st earns (yearly limit for that day's coverage
  //   + $1,000 if 55 or older by Dec 31) / 12  ->  month-by-month limit = sum of those
  //   Last-month rule: eligible on December 1 -> treated as eligible all year with December's
  //   coverage for any month not otherwise covered; the limit is the greater of that chart total
  //   and the full-year amount for December's coverage (Form 8889 line 3 rules 2-4).
  //   Testing period: contributions above the month-by-month limit that rely on the last-month
  //   rule become income (+10% additional tax) unless you stay eligible Dec 1, 2026 - Dec 31, 2027.
  //   You can still contribute = limit - employer contributions - your contributions so far.
  // CHECKS (Node, scratch tests): self-only all year -> $4,400; family all year at 55+ ->
  // $9,750; self-only from July, still eligible in December -> month-by-month $2,200 but
  // last-month rule $4,400 with $2,200 at risk in the testing period; self-only Jan-Jun then
  // eligibility ends, 55+ -> $5,400 x 6/12 = $2,700 (same method as Pub. 969's $5,300 x 6/12
  // example for 2025); self-only Jan-Oct, family Nov-Dec -> $8,750 (family on Dec 1);
  // family Jan-Jun, self-only Jul-Dec -> greater of (6 x 8,750 + 6 x 4,400)/12 = $6,575 and
  // $4,400 = $6,575; $500 employer + $1,200 so far on $4,400 -> $2,700 left, $225 a paycheck
  // over 12; tax saved at 22% + 5% + 7.65% = $935.55; contributions above the limit -> excess.
  // Pub. 969 (2025) testing-period Examples 1 and 2 reproduced with 2026 figures: family from
  // December only -> month-by-month $729.17, $8,020.83 at risk; self-only Jan-Oct then family
  // -> (10 x 4,400 + 2 x 8,750)/12 = $5,125.00, $3,625.00 at risk (same method as the
  // publication's $712.50 / $5,008.33 for 2025).
  // ---- 2026 HSA LIMITS (calendar year 2026) ---------------------------------------------------
  // Source: IRS Rev. Proc. 2025-19 (IRC 223 inflation adjustments for 2026), repeated in IRS
  // Pub. 969 (2025) and Pub. 15-B (2026). Catch-up: IRC 223(b)(3)(B), a fixed $1,000 for
  // account holders 55 or older (not indexed). Last-month rule and testing period: IRC
  // 223(b)(8), IRS Pub. 969. FICA: 6.2% Social Security + 1.45% Medicare (IRC 3101).
  var HSA = { year: 2026, limit: { self: 4400, family: 8750 }, catchUp55: 1000 };
  var FICA_RATE = 0.0765;
  // --------------------------------------------------------------------------------------------
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
                'September', 'October', 'November', 'December'];
  var COVER_NAME = { self: 'Self-only', family: 'Family' };

  // p: coverage, start (1-12), change (bool), changeMonth, newCoverage, loss (bool), end (1-12), age55
  function limitFor(p) {
    var end = p.loss ? p.end : 12, catchUp = p.age55 ? HSA.catchUp55 : 0;
    var rows = [], prorated = 0, months = 0;
    function typeAt(m) { return p.change && m >= p.changeMonth ? p.newCoverage : p.coverage; }
    for (var m = 1; m <= 12; m++) {
      var type = typeAt(m), eligible = m >= p.start && m <= end;
      var yearly = HSA.limit[type] + catchUp, earned = eligible ? yearly / 12 : 0;
      prorated += earned;
      if (eligible) months++;
      rows.push({ month: m, eligible: eligible, type: type, yearly: yearly, earned: earned });
    }
    var lastMonth = end === 12 && p.start <= 12, ruleLimit = 0;
    if (lastMonth) {
      var dec = typeAt(12), filled = 0;
      rows.forEach(function (r) { filled += r.eligible ? r.earned : (HSA.limit[dec] + catchUp) / 12; });
      ruleLimit = Math.max(filled, HSA.limit[dec] + catchUp);
    }
    var limit = Math.max(prorated, ruleLimit);
    return { rows: rows, months: months, prorated: prorated, lastMonth: lastMonth, ruleLimit: ruleLimit,
             limit: limit, atRisk: Math.max(0, limit - prorated) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function val(id) { return document.getElementById(id).value; }

  function update() {
    var p = {
      coverage: val('hcCoverage') === 'family' ? 'family' : 'self',
      start: parseInt(val('hcStart'), 10) || 1,
      change: document.getElementById('hcChange').checked,
      changeMonth: parseInt(val('hcChangeMonth'), 10) || 2,
      newCoverage: val('hcNewCoverage') === 'family' ? 'family' : 'self',
      loss: document.getElementById('hcLoss').checked,
      end: parseInt(val('hcEnd'), 10) || 11,
      age55: document.getElementById('hcAge55').checked
    };
    document.getElementById('hcChangeFields').hidden = !p.change;
    document.getElementById('hcLossFields').hidden = !p.loss;
    var employer = num('hcEmployer'), soFar = num('hcSoFar'), paychecks = num('hcPaychecks'),
        fed = parseFloat(val('hcFed')), state = num('hcState'), payroll = document.getElementById('hcPayroll').checked;
    var error = document.getElementById('hcError'), msg = '';
    if ([employer, soFar, paychecks, fed, state].some(isNaN) || employer < 0 || soFar < 0)
      msg = 'Enter non-negative contribution amounts.';
    else if (paychecks < 0 || paychecks > 52 || Math.round(paychecks) !== paychecks) msg = 'Enter a whole number of paychecks from 0 to 52.';
    else if (state < 0 || state > 15) msg = 'Enter a state tax rate from 0 to 15%.';
    else if (p.loss && p.end < p.start) msg = 'The last eligible month cannot be before the first eligible month.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var r = limitFor(p);
    var used = employer + soFar, remaining = Math.max(0, r.limit - used), excess = Math.max(0, used - r.limit);
    var rate = fed / 100 + state / 100 + (payroll ? FICA_RATE : 0);
    set('hcRemaining', money(remaining));
    set('hcLimit', money(r.limit));
    set('hcPerLabel', paychecks > 0 ? 'Per paycheck (' + paychecks + ' left)' : 'Per paycheck');
    set('hcPer', paychecks > 0 ? money(remaining / paychecks) : 'Lump sum');
    set('hcTax', money(remaining * rate));
    set('hcMonths', r.months + ' of 12');
    set('hcProrated', money(r.prorated));
    set('hcLastMonth', r.lastMonth ? money(r.ruleLimit) : 'Does not apply');
    set('hcLessEr', '−' + money(employer));
    set('hcLessYou', '−' + money(soFar));

    var note = r.lastMonth
      ? 'You are eligible on December 1, ' + HSA.year + ', so the last-month rule lets you use the full-year limit for the coverage you have that day.'
      : 'You are not eligible on December 1, ' + HSA.year + ', so your limit is the month-by-month amount.';
    if (p.coverage === 'family' || (p.change && p.newCoverage === 'family'))
      note += ' Married? If you and your spouse are both eligible and either has family coverage, you share one family limit and split it as you choose; each spouse 55 or older puts their own $1,000 catch-up in their own HSA.';
    set('hcNote', note);

    var testEl = document.getElementById('hcTesting');
    testEl.hidden = !(r.atRisk > 0.005);
    if (r.atRisk > 0.005) testEl.textContent = 'Testing period: ' + money(r.atRisk) + ' of your limit comes only from the last-month rule. ' +
        'To keep it, stay HSA-eligible from December 1, ' + HSA.year + ' through December 31, ' + (HSA.year + 1) +
        '. If you do not (other than through death or disability), that amount is added to your income for the year you lose eligibility, plus a 10% additional tax. ' +
        'If you may change plans or enroll in Medicare in ' + (HSA.year + 1) + ', contribute only ' + money(r.prorated) + ' in total.';
    var exEl = document.getElementById('hcExcess');
    exEl.hidden = !(excess > 0.005);
    if (excess > 0.005) exEl.textContent = 'Contributions are already ' + money(excess) + ' over your limit. Withdraw the excess and its earnings ' +
        'before your tax filing deadline (with extensions) to avoid a 6% excise tax for each year it stays in the account.';

    var body = document.getElementById('hcTable');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [MONTHS[row.month - 1], row.eligible ? COVER_NAME[row.type] : 'Not eligible', row.eligible ? money(row.yearly) : '–', money(row.earned)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
